def build_agent(sandbox):
    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    # Add 4 beams with increased mass and dimensions for better dynamics
    for (xx, yy) in [(4.8, 2.6), (5.0, 2.6), (5.2, 2.6), (5.4, 2.6)]:
        b = sandbox.add_beam(xx, yy, 0.08, 0.32, angle=0, density=10.0)
        sandbox.add_joint(cabin, b, (xx, yy), type="rigid")
        beams.append(b)
    return cabin

