    vel = sandbox.get_vehicle_velocity()

    # Apply force in mud zone to counteract resistance
    if 5.5 <= pos[0] <= 7.5:
        sandbox.apply_force(agent_body, (200.0, 0))

    # Apply force in decel zone to maintain speed
    elif 9.5 <= pos[0] <= 11.0:
        sandbox.apply_force(agent_body, (150.0, 0))

    # Ensure speed meets requirements at speed trap (x=9.0)
    elif pos[0] >= 9.0:
        if vel[0] < 2.8:
            sandbox.apply_force(agent_body, (200.0, 0))

    # Ensure speed meets requirements at checkpoint (x=11.0)
    elif pos[0] >= 11.0:
        if not (1.1 <= vel[0] <= 2.7):
            sandbox.apply_force(agent_body, (150.0, 0))

    # Adjust speed to synchronize with gate timing
    # Gate 1: x=10.0m, angular velocity 1.8 rad/s, open window ±0.56 rad
    if 10.0 <= pos[0] <= 11.5:
        # Calculate gate angle over time
        # Gate 1: initial angle 0.38 rad, angular velocity 1.8 rad/s
        # Open window is from 0.38 - 0.56 = -0.18 rad to 0.38 + 0.56 = 0.94 rad
        # Current time since start: t = (pos[0] - 4.0) / vel[0]
        # But without knowing t, we can't calculate gate angle
        # Heuristic: apply force to maintain speed through gate window
