            sandbox.apply_force(agent_body, (150.0, 0))

    # Gate 2: x=11.5m, angular velocity 0.58 rad/s, open window ±1.50 rad
    if 11.5 <= pos[0] <= 12.5:
        # Gate 2 is open for longer window, so apply less force
